  cpu_intel_die_package_energy_reported_joules: { label: "Die-Package-Energie (überlaufend, J)", hint: "Der Package-Energiezähler dieses Die, in Joule umgerechnet; er läuft über und ist weder Energie des gesamten Package noch Leistung oder Energie über die gesamte Lebensdauer." },
  cpu_intel_die_package_energy_unit_joules: { label: "Die-Package-Energieeinheit", hint: "Joule, die ein Zählschritt des Package-Energiezählers dieses Die darstellt; eine Skalierungskonstante." },
