  cpu_intel_die_package_minimum_power_setting_declared_watts: { label: "Die-Mindestleistung (deklariert)", hint: "Niedrigste Package-Leistungseinstellung, die dieser Die in RAPL deklariert; ein deklarierter Wert, weder gemessene Leistung noch garantierte Obergrenze." },
  cpu_intel_die_package_maximum_power_setting_declared_watts: { label: "Die-Höchstleistung (deklariert)", hint: "Höchste Package-Leistungseinstellung, die dieser Die in RAPL deklariert; ein deklarierter Wert, weder gemessene Leistung noch garantierte Verbrauchsobergrenze." },
